    "Explore the natural direction of heat transfer, entropy, and the limits of heat engines.": "Jelajahi arah alami perpindahan kalor, entropi, dan batas kemampuan mesin kalor.",
    "Why Processes Have a Direction": "Mengapa Proses Memiliki Arah",
    "The First Law accounts for conservation of energy, but does not tell us which thermodynamic processes can occur spontaneously. The Second Law sets the direction and limits of those processes.": "Hukum I menjelaskan kekekalan energi, tetapi tidak menentukan proses termodinamika mana yang berlangsung spontan. Hukum II menjelaskan arah dan batas proses tersebut.",
