    "Start with Practice Quiz, then try Live Quiz when you are ready to compete.": "Mulai dari Kuis Latihan, lalu coba Kuis Langsung saat siap berkompetisi.",
    "Waiting Room": "Ruang Tunggu",
    "Share the room code with other players. The player list updates automatically as they join.": "Bagikan kode ruang kepada pemain lain. Daftar pemain diperbarui otomatis ketika mereka bergabung.",
    "Realtime": "Langsung",
    "Loading players...": "Memuat pemain...",
    "Waiting for host to start the quiz...": "Menunggu host memulai kuis...",
    "What is the SI unit of heat energy?": "Apa satuan SI untuk energi kalor?",
    "The SI unit of heat energy is the joule (J).": "Satuan SI untuk energi kalor adalah joule (J).",
    "Which equation is commonly used to calculate heat transferred during a temperature change?": "Persamaan manakah yang biasa digunakan untuk menghitung kalor selama perubahan temperatur?",
    "For sensible heating or cooling, heat transfer is calculated using Q = mcΔT.": "Untuk pemanasan atau pendinginan tanpa perubahan fase, perpindahan kalor dihitung dengan Q = mcΔT.",
    "How does heat naturally flow between two objects at different temperatures?": "Bagaimana kalor mengalir secara alami antara dua benda dengan temperatur berbeda?",
    "From lower to higher temperature": "Dari temperatur rendah ke temperatur tinggi",
    "From higher to lower temperature": "Dari temperatur tinggi ke temperatur rendah",
    "It does not flow": "Tidak mengalir",
    "It always flows toward the larger object": "Selalu mengalir menuju benda yang lebih besar",
    "Heat naturally transfers from a higher-temperature region to a lower-temperature region.": "Kalor secara alami berpindah dari daerah bersuhu tinggi ke daerah bersuhu rendah.",
    "What does specific heat capacity describe?": "Apa yang dijelaskan oleh kalor jenis?",
    "Energy required to raise the temperature of unit mass by one degree": "Energi untuk menaikkan temperatur setiap satuan massa sebesar satu derajat",
    "Pressure generated by one mole of gas": "Tekanan yang dihasilkan satu mol gas",
    "Work done per unit time": "Usaha yang dilakukan per satuan waktu",
    "Volume occupied by one joule of energy": "Volume yang ditempati satu joule energi",
    "Specific heat capacity tells us how much energy is needed to raise the temperature of a unit mass by one degree.": "Kalor jenis menunjukkan energi yang diperlukan untuk menaikkan temperatur satu satuan massa sebesar satu derajat.",
    "If an object's final temperature is lower than its initial temperature, what is the sign of ΔT = Tfinal − Tinitial?": "Jika temperatur akhir suatu benda lebih rendah daripada temperatur awal, apa tanda ΔT = Takhir − Tawal?",
    "Positive": "Positif",
    "Negative": "Negatif",
    "Always zero": "Selalu nol",
    "Undefined": "Tidak terdefinisi",
    "When Tfinal is lower than Tinitial, subtracting the larger initial temperature gives a negative ΔT.": "Jika Takhir lebih rendah daripada Tawal, pengurangan temperatur awal yang lebih besar menghasilkan ΔT negatif.",
    "For a constant-pressure expansion, which expression represents boundary work?": "Pada ekspansi tekanan tetap, persamaan mana yang menyatakan usaha batas?",
    "At constant pressure, boundary work is pressure multiplied by the change in volume.": "Pada tekanan tetap, usaha batas sama dengan tekanan dikalikan perubahan volume.",
    "When a gas expands against its surroundings, what happens to its volume?": "Apa yang terjadi pada volume gas saat gas memuai melawan lingkungannya?",
    "It increases": "Bertambah",
    "It decreases": "Berkurang",
    "It remains zero": "Tetap nol",
    "It becomes negative": "Menjadi negatif",
    "Expansion means the system occupies a larger volume.": "Ekspansi berarti sistem menempati volume yang lebih besar.",
    "Internal energy is best described as which type of property?": "Energi dalam paling tepat termasuk jenis sifat apa?",
    "A state property": "Sifat keadaan",
    "A path only": "Hanya lintasan",
    "A unit of pressure": "Satuan tekanan",
    "A type of volume": "Jenis volume",
    "Internal energy depends on the state of the system, not on the path used to reach that state.": "Energi dalam bergantung pada keadaan sistem, bukan pada lintasan yang ditempuh untuk mencapainya.",
    "If the volume does not change during a process, what is the boundary work W = PΔV?": "Jika volume tidak berubah selama proses, berapa usaha batas W = PΔV?",
    "Zero": "Nol",
    "Maximum": "Maksimum",
    "Always negative": "Selalu negatif",
    "Equal to heat transfer": "Sama dengan perpindahan kalor",
    "With no change in volume, ΔV = 0, so boundary work is zero.": "Jika volume tidak berubah, ΔV = 0 sehingga usaha batas sama dengan nol.",
    "Which SI unit is used for both work and energy?": "Satuan SI apa yang digunakan untuk usaha dan energi?",
    "Meter": "Meter",
    "Work and energy are both measured in joules (J) in SI units.": "Usaha dan energi sama-sama diukur dalam joule (J) pada sistem SI.",
    "Which equation represents the First Law using the convention that W is work done by the system?": "Persamaan manakah yang menyatakan Hukum I dengan konvensi W positif saat sistem melakukan usaha?",
    "With work done by the system taken as positive, the First Law is ΔU = Q − W.": "Jika usaha oleh sistem bernilai positif, Hukum I dituliskan ΔU = Q − W.",
    "A system receives 1000 J of heat and does 300 J of work. What is ΔU?": "Sistem menerima kalor 1000 J dan melakukan usaha 300 J. Berapakah ΔU?",
    "Using ΔU = Q − W gives 1000 J − 300 J = 700 J.": "Dengan ΔU = Q − W diperoleh 1000 J − 300 J = 700 J.",
    "In the First Law, which quantity represents energy transferred because of a temperature difference?": "Dalam Hukum I, besaran apa yang menyatakan energi yang berpindah akibat perbedaan temperatur?",
    "Volume (V)": "Volume (V)",
    "Q represents heat transfer between the system and surroundings.": "Q menyatakan perpindahan kalor antara sistem dan lingkungan.",
    "For a complete thermodynamic cycle, what is the net change in internal energy?": "Untuk satu siklus termodinamika penuh, berapakah perubahan bersih energi dalam?",
    "Always positive": "Selalu positif",
    "Equal to pressure": "Sama dengan tekanan",
    "A cycle returns to its initial state, so the state property internal energy has no net change.": "Siklus mengembalikan sistem ke keadaan awal sehingga energi dalam sebagai sifat keadaan tidak mengalami perubahan bersih.",
    "Which statement best expresses the energy-conservation idea behind the First Law?": "Pernyataan mana yang paling tepat menggambarkan kekekalan energi pada Hukum I?",
    "Energy can change form but is conserved": "Energi dapat berubah bentuk, tetapi jumlahnya tetap",
    "Energy can be created from nothing": "Energi dapat diciptakan dari ketiadaan",
