    "Nine quantities. One laboratory. Choose your units, enter a value, and compare the result instantly.": "Sembilan besaran. Satu laboratorium. Pilih satuan, masukkan nilai, dan bandingkan hasilnya seketika.",
    "SI + everyday units": "SI + satuan sehari-hari",
