    "Kalor Jenis c": "Specific Heat c",
    "Diagram Kalor-Temperatur": "Heat-Temperature Diagram",
    "Hubungan antara kalor yang diberikan dan temperatur.": "Relationship between supplied heat and temperature.",
    "Kalor dan Temperatur": "Heat and Temperature",
    "Kalor merupakan energi yang berpindah antarbenda akibat perbedaan temperatur. Saat bahan menerima kalor, temperaturnya dapat meningkat.": "Heat is energy transferred between objects because of a temperature difference. When heat is supplied to a material, its temperature can increase.",
    "Kalor yang diberikan (J)": "Heat supplied (J)",
    "Apa yang terjadi saat kalor diberikan?": "What happens when heat is supplied?",
    "Ketika bahan menerima kalor, energi partikel-partikelnya meningkat. Partikel bergerak lebih aktif sehingga temperaturnya dapat naik.": "When a material receives heat, the energy of its particles increases. The particles move more actively, which can result in an increase in temperature.",
    "Apa itu kalor jenis?": "What is specific heat?",
    "Kalor jenis adalah jumlah kalor yang diperlukan untuk menaikkan temperatur 1 kg bahan sebesar 1 K.": "Specific heat is the amount of heat required to increase the temperature of 1 kg of a material by 1 K.",
    "Mengapa massa memengaruhi perubahan temperatur?": "Why does mass affect temperature change?",
    "Untuk jumlah kalor yang sama, massa yang lebih besar membutuhkan lebih banyak energi agar kenaikan temperaturnya sama.": "For the same amount of supplied heat, a larger mass requires more energy to produce the same temperature increase.",
    "Bagaimana cara membaca simulasi?": "How do I read the simulation?",
    "Arahkan kursor ke air, api, termometer, atau partikel untuk melihat nilai terkini. Kamu juga dapat mengarahkan kursor ke grafik untuk memeriksa suatu titik.": "Move the cursor over the water, flame, thermometer, or particles to see their current values. You can also move the cursor over the graph to inspect a specific point.",
    "Contoh": "Example",
    "Misalkan air bermassa 1 kg menerima kalor 42.000 J. Jika kalor jenis air sekitar 4.200 J/kg·K:": "Suppose 42,000 J of heat is supplied to 1 kg of water. Since the specific heat of water is approximately 4,200 J/kg·K:",
    "Jika temperatur awal 25 °C, temperatur akhirnya sekitar 35 °C.": "If the initial temperature is 25 °C, the final temperature becomes approximately 35 °C.",
    "Gagasan Utama": "Key Idea",
    "Besarnya perubahan temperatur bergantung pada kalor yang diberikan, massa, dan kalor jenis bahan.": "The amount of temperature change depends on the supplied heat, mass, and specific heat of the material.",
    "Jelajahi kesetimbangan termal antara Sistem A, B, dan C melalui gerak partikel, pertukaran temperatur, dan perpindahan kalor.": "Explore how thermal equilibrium works between System A, System B, and System C through particle motion, temperature exchange, and heat transfer.",
    "Jika Sistem A berada dalam kesetimbangan termal dengan Sistem C, dan Sistem B juga berada dalam kesetimbangan termal dengan Sistem C, maka Sistem A dan Sistem B berada dalam kesetimbangan termal.": "If System A is in thermal equilibrium with System C, and System B is also in thermal equilibrium with System C, then System A and System B are in thermal equilibrium.",
    "Simulasi Kesetimbangan Termal": "Thermal Equilibrium Simulation",
    "Belum Setimbang": "Not in Equilibrium",
