    "Sistem berada pada temperatur yang sangat rendah. Partikel hanya mengalami getaran kecil di sekitar posisi keseimbangannya.": "The system is at a very low temperature. Particles vibrate only slightly around their equilibrium positions.",
    "Ketika temperatur semakin rendah, gerakan termal partikel berkurang dan keteraturan kristal meningkat.": "As temperature decreases, particle thermal motion decreases and crystal order increases.",
    "Temperatur sedang menyebabkan partikel tetap bergetar di sekitar posisi keseimbangannya.": "Moderate temperatures keep particles vibrating around their equilibrium positions.",
    "Temperatur yang lebih tinggi menyebabkan energi termal dan gerakan partikel menjadi lebih besar.": "Higher temperatures increase thermal energy and particle motion.",
