    "Atur Ulang": "Reset",
    "DATA SIMULASI": "SIMULATION DATA",
    "Amati perpindahan energi saat gas melakukan usaha pada piston.": "Observe the energy transfer as the gas performs work on the piston.",
    "Perpindahan Piston": "Piston Displacement",
    "DIAGRAM USAHA": "WORK DIAGRAM",
    "Diagram Gaya–Perpindahan": "Force–Displacement Diagram",
    "Luas di bawah kurva menyatakan usaha yang dilakukan gas.": "The area under the curve represents the work done by the gas.",
    "TEKANAN KONSTAN": "CONSTANT PRESSURE",
    "Usaha Termodinamika": "Thermodynamic Work",
    "Pada tekanan konstan, usaha sama dengan tekanan dikalikan perubahan volume.": "For constant pressure, work equals pressure multiplied by the change in volume.",
    "PROSES UMUM": "GENERAL PROCESS",
    "Usaha dinyatakan oleh luas di bawah kurva proses pada diagram P–V.": "The work corresponds to the area under the process curve on a P–V diagram.",
    "KONSEP PENTING": "KEY CONCEPTS",
    "Energi yang berpindah ketika gaya menyebabkan perpindahan batas sistem.": "Energy transferred when a force causes displacement of a system boundary.",
    "Pelajari Konsep Work & Energy": "Learn about Work & Energy",
    "Apa itu Work dalam Termodinamika?": "What is work in thermodynamics?",
    "Work atau usaha adalah energi yang berpindah akibat adanya gaya yang menyebabkan perpindahan batas sistem. Pada simulator ini, work terjadi ketika gas mendorong piston ke atas.": "Work is energy transferred when a force causes displacement of a system boundary. In this simulator, work occurs when the gas pushes the piston upward.",
    "Apa itu Internal Energy?": "What is internal energy?",
    "Internal energy atau energi dalam adalah energi mikroskopis yang tersimpan dalam sistem dan berkaitan dengan gerak serta interaksi partikel penyusunnya.": "Internal energy is the microscopic energy stored in a system, associated with the motion and interactions of its constituent particles.",
    "Apa Perbedaan Heat, Work, dan Internal Energy?": "How do heat, work, and internal energy differ?",
    "Heat dan work merupakan mekanisme perpindahan energi, sedangkan internal energy merupakan energi yang tersimpan dalam sistem.": "Heat and work are mechanisms of energy transfer, while internal energy is energy stored in the system.",
    "Bagaimana Work Terjadi pada Gas?": "How does a gas do work?",
    "Ketika gas mengembang, gas memberikan gaya pada piston sehingga piston berpindah. Perpindahan piston tersebut menunjukkan bahwa gas melakukan work terhadap lingkungan.": "As the gas expands, it exerts a force on the piston, causing it to move. This displacement shows that the gas does work on its surroundings.",
    "Apa Hubungan Force dan Displacement?": "What is the relationship between force and displacement?",
    "Untuk gaya konstan, work dapat dihitung menggunakan W = F × Δx. Semakin besar gaya atau semakin jauh piston berpindah, semakin besar work yang dilakukan.": "For a constant force, work is calculated as W = F × Δx. A larger force or a greater piston displacement produces more work.",
    "Bagaimana Membaca Diagram P–V?": "How do you read a P–V diagram?",
    "Pada diagram P–V, work pada suatu proses dapat dipahami sebagai luas daerah di bawah kurva. Untuk tekanan konstan, daerah tersebut berbentuk persegi panjang.": "On a P–V diagram, work during a process is represented by the area under the curve. At constant pressure, this area is a rectangle.",
    "HUBUNGAN ENERGI": "ENERGY RELATION",
    "Ketika sistem menerima energi sebagai kalor, sebagian energi dapat digunakan untuk melakukan work dan sisanya mengubah internal energy.": "When a system receives energy as heat, some of it can be used to do work while the rest changes its internal energy.",
    "Pembelajaran Termodinamika Interaktif": "Interactive Thermodynamics Learning",
    "Simulasi Hukum 0 Termodinamika": "Zeroth Law of Thermodynamics Simulation",
    "Simulasi Interaktif Hukum 0 Termodinamika": "Interactive Zeroth Law of Thermodynamics Simulation",
    "Jika sistem A berada dalam kesetimbangan termal dengan sistem C, dan sistem B juga berada dalam kesetimbangan termal dengan sistem C, maka sistem A dan sistem B berada dalam kesetimbangan termal satu sama lain.": "If system A is in thermal equilibrium with system C, and system B is also in thermal equilibrium with system C, then systems A and B are in thermal equilibrium with each other.",
    "Termometer": "Thermometer",
    "Kalor berpindah dari benda bersuhu lebih tinggi ke benda bersuhu lebih rendah.": "Heat flows from a higher-temperature object to a lower-temperature object.",
    "Kontrol Temperatur": "Temperature Controls",
    "Temperatur Sistem A": "System A Temperature",
    "Temperatur Sistem B": "System B Temperature",
    "Temperatur Termometer": "Thermometer Temperature",
    "Prinsip Hukum 0:": "Zeroth Law principle:",
    "Temperatur menentukan keadaan termal suatu sistem. Jika dua sistem mencapai temperatur yang sama, tidak terjadi perpindahan kalor bersih di antara keduanya.": "Temperature determines the thermal state of a system. When two systems reach the same temperature, there is no net heat transfer between them.",
    "BANK SOAL": "QUESTION BANK",
    "T = konstan &nbsp; · &nbsp; P1V1 = P2V2": "T = constant &nbsp; · &nbsp; P1V1 = P2V2",
    "P = konstan &nbsp; · &nbsp; V1/T1 = V2/T2": "P = constant &nbsp; · &nbsp; V1/T1 = V2/T2",
    "V = konstan &nbsp; · &nbsp; ΔV = 0 &nbsp; · &nbsp; W = 0": "V = constant &nbsp; · &nbsp; ΔV = 0 &nbsp; · &nbsp; W = 0",
    "Kristal sempurna &nbsp; · &nbsp; T → 0 K &nbsp; ⇒ &nbsp; S → 0": "Perfect crystal &nbsp; · &nbsp; T → 0 K &nbsp; ⇒ &nbsp; S → 0",
    "TA = TB &nbsp; dan &nbsp; TB = TC∴ &nbsp; TA = TC": "TA = TB &nbsp; and &nbsp; TB = TC∴ &nbsp; TA = TC",
    "Ttubuh = Ttermometer": "Tbody = Tthermometer",
