    "Seorang anggota kolaboratif dalam THERMPYX yang membantu mewujudkan ide tim menjadi pengalaman belajar interaktif. THERMPYX menjadi salah satu kesempatan pertamanya untuk mengeksplorasi media pembelajaran digital.": "A collaborative contributor in THERMPYX who helps turn the team's ideas into an interactive learning experience. THERMPYX became one of his first opportunities to explore digital learning media.",
    "Berfokus pada sisi teknis dan logika THERMPYX. Melalui proyek ini, John mengeksplorasi bagaimana logika sistem dan teknologi web dapat mendukung pengalaman pembelajaran interaktif.": "Focused on the technical and logical side of THERMPYX. Through this project, John explores how system logic and web technology can support an interactive educational experience.",
    "Berkontribusi dalam THERMPYX melalui eksplorasi, riset, dan penyempurnaan berkelanjutan. Proyek ini menjadi kesempatan untuk melihat bagaimana ide sains dapat diubah menjadi media pembelajaran interaktif.": "Contributes to THERMPYX through exploration, research, and continuous refinement. The project provides an opportunity to experience how scientific ideas can become interactive learning media.",
    "Berfokus pada pengalaman visual dan desain antarmuka. Melalui THERMPYX, Naspad mengeksplorasi bagaimana layout, interaksi, dan identitas visual dapat membuat pembelajaran sains lebih jelas dan menarik.": "Focused on visual experience and interface design. Through THERMPYX, Naspad explores how layout, interaction, and visual identity can make scientific learning clearer and more engaging.",
