  "Q̇ = kAΔT/d = 0,8 × 5 × 20/0,2 = 400 W.": "Q̇ = kAΔT/d = 0,8 × 5 × 20/0,2 = 400 W.",
  "Tf = (CbTb + CsTs)/(Cb + Cs)": "Tf = (CbTb + CsTs)/(Cb + Cs)",
  "430Tf = 16.800 + 200 = 17.000.": "430Tf = 16.800 + 200 = 17.000.",
  "Tf = 17.000/430 = 39,53 °C.": "Tf = 17.000/430 = 39,53 °C.",
  "dW = F dx = Pext A dx = Pext dV; W = ∫Pext dV": "dW = F dx = Pext A dx = Pext dV; W = ∫Pext dV",
  "U = (f/2)nRT; ΔU = nCvΔT; Cv = (f/2)R": "U = (f/2)nRT; ΔU = nCvΔT; Cv = (f/2)R",
  "Pext = 100 kPa; ΔV = 3 L.": "Pext = 100 kPa; ΔV = 3 L.",
  "W = 100 × 3 kPa·L.": "W = 100 × 3 kPa·L.",
  "W = −450 kPa·L = −450 J.": "W = −450 kPa·L = −450 J.",
  "W = Prata-rataΔV = 150 × (4 − 1).": "W = Prata-rataΔV = 150 × (4 − 1).",
  "n = 2 mol; Cv = 3R/2; ΔT = 100 K.": "n = 2 mol; Cv = 3R/2; ΔT = 100 K.",
  "ΔU ≈ +2,49 kJ.": "ΔU ≈ +2,49 kJ.",
  "ΔP = 200 kPa; ΔV = 3 L.": "ΔP = 200 kPa; ΔV = 3 L.",
  "Wnet = ΔPΔV = 200 × 3 = 600 J.": "Wnet = ΔPΔV = 200 × 3 = 600 J.",
  "Qv = nCvΔT; Qp = nCpΔT; Cp − Cv = R": "Qv = nCvΔT; Qp = nCpΔT; Cp − Cv = R",
  "H = U + PV; q − w = h₂ − h₁": "H = U + PV; q − w = h₂ − h₁",
  "ΔT = ΔU/(nCv) = −1.200/40 = −30 K.": "ΔT = ΔU/(nCv) = −1.200/40 = −30 K.",
  "Qnet = 2.000 − 1.400 = 600 J.": "Qnet = 2.000 − 1.400 = 600 J.",
  "Materi lengkap tersedia dalam Bahasa Indonesia dan Inggris. Baca konsep dan syarat rumus terlebih dahulu, lalu ikuti lima contoh soal dengan penyelesaiannya. Tanda yang dipakai: Q positif untuk kalor masuk dan W positif untuk usaha oleh sistem.": "Complete material is available in Indonesian and English. Read the concepts and the conditions for each formula first, then follow five fully worked examples. Sign convention: Q is positive for heat entering the system and W is positive for work done by the system.",
  "Tujuh topik termodinamika dengan 35 contoh soal lengkap. Pilih pembahasan konsep dan rumus atau langsung buka contoh soal beserta penyelesaiannya. Seluruh materi lengkap tersedia dalam Bahasa Indonesia dan Inggris.": "Seven thermodynamics topics with 35 fully worked examples. Choose a discussion of concepts and formulas or open the examples and their solutions directly. Complete material is available in Indonesian and English.",
  "Materi diperluas": "Extended material",
  "Teori mendalam, penjelasan rumus, serta 5 contoh soal lengkap tersedia pada halaman ini.": "This page includes in-depth theory, formula explanations, and 5 fully worked examples.",
